def dfs(i, val, cnt, left):
    if val > best[0] or (val == best[0] and cnt < best[1]):
        best[0] = val
        best[1] = cnt
        best[2] = list(chosen)
    if i >= G:
        return
    ub = val + suff_val[i]
    if ub < best[0] or (ub == best[0] and cnt >= best[1]):
        return
    su = suff_use[i]
    tight = []
    for n in range(m):
        if su[n] > left[n]:
            tight.append(n)
    if not tight:
        v = ub
        c = cnt + suff_cnt[i]
        if v > best[0] or (v == best[0] and c < best[1]):
            best[0] = v
            best[1] = c
            best[2] = chosen + [f for g in gl[i:] for f in g[3]]
        return
    if tight:
        # relaxation bound: at most left[n] remaining items may touch node n
        for n in tight if len(tight) <= 6 else tight[:6]:
            lst = node_groups[n]
            p0 = bisect_left(lst, i)
            if p0 >= len(lst):
                continue
            rem = left[n]
            acc = 0
            q = p0
            while q < len(lst) and rem > 0:
                b, _nodes, k, _f = gl[lst[q]]
                take = k if k < rem else rem
                acc += take * b
                rem -= take
                q += 1
            cand = ub - node_suff[n][p0] + acc
            if cand < best[0] or (cand == best[0] and cnt >= best[1]):
                return
    key = (i, tuple(left))
    prev = seen.get(key)
    if prev is None:
        seen[key] = [(val, cnt)]
    else:
        for pv, pc in prev:
            if pv >= val and pc <= cnt:
                return
        prev.append((val, cnt))
    cap = 0
    for n in range(m):
        cap += left[n]
    if cap < suff_cnt[i]:
        # 1D relaxation: each chosen item consumes one free slot at every
        # binding node it uses, so total slot demand is bounded by cap
        acc = 0
        rem = cap
        for j, b, wn, k in ratio_items:
            if j < i:
                continue
            if wn == 0:
                acc += b * k
                continue
            while k and rem > 0:
                if rem >= wn:
                    acc += b
                    rem -= wn
                    k -= 1
                else:
                    acc += (b * rem + wn - 1) // wn
                    rem = 0
            if rem <= 0:
                continue
        cand = val + acc
        if cand < best[0] or (cand == best[0] and cnt >= best[1]):
            return
    b, nodes, k, fids = gl[i]
    jm = k
    for n in nodes:
        if left[n] < jm:
            jm = left[n]
    for j in range(jm, 0, -1):
        nv = val + j * b
        if nv + suff_val[i + 1] < best[0]:
            break
        if nv + suff_val[i + 1] == best[0] and cnt + j >= best[1]:
            continue
        for n in nodes:
            left[n] -= j
        chosen.extend(fids[:j])
        dfs(i + 1, nv, cnt + j, left)
        del chosen[-j:]
        for n in nodes:
            left[n] += j
    dfs(i + 1, val, cnt, left)

